diff --git a/db/compaction/compaction_picker_level.cc b/db/compaction/compaction_picker_level.cc
index 28c565b1b..0a70c89c0 100644
--- a/db/compaction/compaction_picker_level.cc
+++ b/db/compaction/compaction_picker_level.cc
@@ -358,61 +358,61 @@ Compaction* LevelCompactionBuilder::GetCompaction() {
  * up to and including this path
  */
 uint32_t LevelCompactionBuilder::GetPathId(
     const ImmutableCFOptions& ioptions,
     const MutableCFOptions& mutable_cf_options, int level) {
   uint32_t p = 0;
   assert(!ioptions.cf_paths.empty());

   // size remaining in the most recent path
   uint64_t current_path_size = ioptions.cf_paths[0].target_size;

   uint64_t level_size;
   int cur_level = 0;

   // max_bytes_for_level_base denotes L1 size.
   // We estimate L0 size to be the same as L1.
   level_size = mutable_cf_options.max_bytes_for_level_base;

   // Last path is the fallback
   while (p < ioptions.cf_paths.size() - 1) {
     if (level_size <= current_path_size) {
       if (cur_level == level) {
         // Does desired level fit in this path?
         return p;
       } else {
         current_path_size -= level_size;
         if (cur_level > 0) {
           if (ioptions.level_compaction_dynamic_level_bytes) {
             // Currently, level_compaction_dynamic_level_bytes is ignored when
             // multiple db paths are specified. https://github.com/facebook/
-            // rocksdb/blob/master/db/column_family.cc.
+            // rocksdb/blob/main/db/column_family.cc.
             // Still, adding this check to avoid accidentally using
             // max_bytes_for_level_multiplier_additional
             level_size = static_cast<uint64_t>(
                 level_size * mutable_cf_options.max_bytes_for_level_multiplier);
           } else {
             level_size = static_cast<uint64_t>(
                 level_size * mutable_cf_options.max_bytes_for_level_multiplier *
                 mutable_cf_options.MaxBytesMultiplerAdditional(cur_level));
           }
         }
         cur_level++;
         continue;
       }
     }
     p++;
     current_path_size = ioptions.cf_paths[p].target_size;
   }
   return p;
 }

 bool LevelCompactionBuilder::PickFileToCompact() {
   // level 0 files are overlapping. So we cannot pick more
   // than one concurrent compactions at this level. This
   // could be made better by looking at key-ranges that are
   // being compacted at level 0.
   if (start_level_ == 0 &&
       !compaction_picker_->level0_compactions_in_progress()->empty()) {
     TEST_SYNC_POINT("LevelCompactionPicker::PickCompactionBySize:0");
     return false;
   }

