   ASSERT_EQ(a == 0U, b == 0U);
   if (a == 0) {
     return;
   }
   double dbl_a = static_cast<double>(a);
   double dbl_b = static_cast<double>(b);
   if (dbl_a > dbl_b) {
     ASSERT_LT(static_cast<double>(dbl_a - dbl_b) / (dbl_a + dbl_b), bias);
