+  const jsize num_keys = env->GetArrayLength(jkeys);
+
+  std::unique_ptr<jint[]> key_offs = std::make_unique<jint[]>(num_keys);
+  env->GetIntArrayRegion(jkey_offs, 0, num_keys, key_offs.get());
+  if (env->ExceptionCheck()) {
