                      *smallest_) < 0) {
     iter_->Invalidate();
     return;
   }
   if (largest_ != nullptr &&
       icmp_->user_comparator()->Compare(largest_->user_key, target) < 0) {
     iter_->SeekForPrev(largest_->user_key);
     return;
   }
   iter_->SeekForPrev(target);
 }

