     assert(!f->refs_);
     uint64_t file_size;
     if (!f->Delete(&file_size).ok()) {
       // unable to delete file
       return false;
     }

     assert(file_size <= size_);
     size_ -= file_size;
   }

   size_ += size;
   assert(size_ <= opt_.cache_size * 0.9);
