 bool LDBCommand::StringToBool(std::string val) {
   std::transform(val.begin(), val.end(), val.begin(),
                  [](char ch) -> char { return (char)::tolower(ch); });

   if (val == "true") {
     return true;
   } else if (val == "false") {
     return false;
   } else {
     throw "Invalid value for boolean argument";
   }
 }

