       } else {
         earliest_log_nums[i] = port::kMaxUint64;
       }
     }
     // Check at least the first WAL was cleaned up during the recovery.
     ASSERT_LT(earliest_log_nums[0], earliest_log_nums[1]);
   } while (ChangeWalOptions());
